<div class="grid gap-5 md:grid-cols-4"><?php foreach ($stats as $label => $value): ?><div class="rounded-3xl border border-white/10 bg-white/5 p-6"><p class="text-sm capitalize text-slate-400"><?= e($label) ?></p><b class="text-4xl"><?= e($value) ?></b></div><?php endforeach; ?></div><section class="mt-8 rounded-3xl border border-white/10 bg-white/5 p-6"><h2 class="text-2xl font-black">Admin Modules</h2><div class="mt-5 grid gap-4 md:grid-cols-4"><?php foreach (['Approve/reject products','Vendor verification','Revenue analytics','Global SEO settings','Coupon management','Order management','License management','Security logs'] as $module): ?><div class="rounded-2xl bg-white/5 p-4 font-bold"><i class='bx bx-check text-cyan-300'></i> <?= e($module) ?></div><?php endforeach; ?></div></section><section class="mt-8"><h2 class="mb-4 text-2xl font-black">Recent Products</h2><div class="overflow-x-auto"><table class="admin-table"><tr><th>Name</th><th>Type</th><th>Status</th><th>Sales</th></tr><?php foreach ($recent as $product): ?><tr><td><?= e($product['name']) ?></td><td><?= e($product['product_type']) ?></td><td><?= e($product['approval_status']) ?></td><td><?= (int) $product['total_sales'] ?></td></tr><?php endforeach; ?></table></div></section>
